import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";import"./chunks/assets.ByxXdwmG.js";var i=JSON.parse(`{"title":"サイト設定と共通デザイン","description":"","frontmatter":{},"headers":[],"relativePath":"guides/sites.md","filePath":"guides/sites.md","lastUpdated":1793675806000}`),a={name:`guides/sites.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="サイト設定と共通デザイン" tabindex="-1">サイト設定と共通デザイン <a class="header-anchor" href="#サイト設定と共通デザイン" aria-label="Permalink to “サイト設定と共通デザイン”">​</a></h1><p>ヘッダーで対象サイトを選び、「サイト設定」を開きます。サイト管理者またはSuperuserが変更できます。新しいサイトの追加はSuperuserが「JevSense管理」で行います。</p><h2 id="基本設定" tabindex="-1">基本設定 <a class="header-anchor" href="#基本設定" aria-label="Permalink to “基本設定”">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>入力例・意味</th></tr></thead><tbody><tr><td>サイト名</td><td>管理画面で使う名前。後から変更可能</td></tr><tr><td>サイトID</td><td>SDKのdata-siteと一致。作成後は変更不可</td></tr><tr><td>許可するオリジン</td><td><a href="https://example.com" target="_blank" rel="noreferrer">https://example.com</a>。パス・末尾スラッシュなし</td></tr><tr><td>収集する経路</td><td>/ja/。前方一致、1行に1つ</td></tr><tr><td>収集しない経路</td><td>/ja/account、/ja/checkout、/ja/search等</td></tr><tr><td>メタデータ送信</td><td>対象ページの情報を確認してから有効化</td></tr><tr><td>有効な閲覧の表示時間</td><td>ミリ秒。短時間表示を判断材料から除く基準</td></tr><tr><td>必要な有効閲覧数</td><td>判定を始めるための有効ページ閲覧数</td></tr></tbody></table><p>新設サイトは送信と施策が無効です。設定を確認して「設定を保存」します。収集範囲の変更後は対象ページを再読み込みし、SDKに新しい設定を読み込ませます。</p><h3 id="オリジンとパスの違い" tabindex="-1">オリジンとパスの違い <a class="header-anchor" href="#オリジンとパスの違い" aria-label="Permalink to “オリジンとパスの違い”">​</a></h3><p><code>https://adobe.customer-experience.dev/ja/</code>を対象にする例です。</p><ul><li>オリジン：<code>https://adobe.customer-experience.dev</code></li><li>収集する経路：<code>/ja/</code></li><li>表示ページ：施策側で、たとえば完全一致<code>/ja/</code></li></ul><p>収集する範囲と表示するページは別です。商品ページを判断材料として集め、トップページだけに案内を表示できます。</p><h2 id="追加イベントと状態" tabindex="-1">追加イベントと状態 <a class="header-anchor" href="#追加イベントと状態" aria-label="Permalink to “追加イベントと状態”">​</a></h2><p>独自クリック・応募・予約・カートなどを連携する場合だけ、イベント名・状態名を登録します。SDKは登録済みの名前だけを受け付けます。<a href="./../integration/sdk#任意のイベント・状態">追加連携</a>を参照してください。</p><h2 id="サイト共通の基本デザイン" tabindex="-1">サイト共通の基本デザイン <a class="header-anchor" href="#サイト共通の基本デザイン" aria-label="Permalink to “サイト共通の基本デザイン”">​</a></h2><p>「共通デザイン」ではそのサイトの全標準施策へ適用する見た目を設定します。</p><table tabindex="0"><thead><tr><th>対象</th><th>調整内容</th></tr></thead><tbody><tr><td>共通</td><td>背景・文字・ボタン色、フォント、文字サイズ、角丸、余白</td></tr><tr><td>モーダル</td><td>幅、背面の暗さ</td></tr><tr><td>フローティング</td><td>幅、右下/左下、画面端との余白</td></tr><tr><td>通知バー</td><td>上部/下部</td></tr></tbody></table><p><img src="/jev-personalization/images/design.png" alt="共通デザイン" width="1440" height="1892"></p><p>右のプレビューで形式を切り替えながら確認できます。入力中の変更は保存するまでサイトへ反映しません。保存すると配信中の施策にも適用します。</p><h2 id="独自javascriptの許可" tabindex="-1">独自JavaScriptの許可 <a class="header-anchor" href="#独自javascriptの許可" aria-label="Permalink to “独自JavaScriptの許可”">​</a></h2><p>サイト単位で許可します。コードの作成・変更・プレビューはサイト管理者またはSuperuserだけが行えます。コードはサイトと同じ権限で動くため、信頼できるものだけを登録します。<a href="./presentation">表示形式と独自コード</a>も確認してください。</p><h2 id="サイトごとのjev接続" tabindex="-1">サイトごとのJev接続 <a class="header-anchor" href="#サイトごとのjev接続" aria-label="Permalink to “サイトごとのJev接続”">​</a></h2><p>左メニューの<a href="./jev">Jev連携</a>でサイト専用のAPIキーと利用停止を設定します。サイト設定JSONやSDKタグへキーを記入する必要はありません。操作と利用記録の閲覧はサイト管理者/Superuserだけが行えます。</p><h2 id="ページ情報の取得と実ページ確認" tabindex="-1">ページ情報の取得と実ページ確認 <a class="header-anchor" href="#ページ情報の取得と実ページ確認" aria-label="Permalink to “ページ情報の取得と実ページ確認”">​</a></h2><p>「ページ情報の取得」タブで、このサイト共通の取得方法を設定します。変更できるのはサイト管理者・Superuserです。</p><ol><li><strong>標準の自動取得</strong>か<strong>サイト独自のルール</strong>を選ぶ。標準はページ名をOGP → title、説明をOGP → meta descriptionの順に取得します。JSON-LDを使う場合はカスタムにします。</li><li>カスタムでは候補を上から並べる。「編集」で条件、ページ名・説明の取得元とキー、接頭辞、説明がない場合の扱いを設定します。条件は同じJSON-LDオブジェクトに対して評価されます。</li><li>右側の<strong>確認するページURL</strong>へ、登録済みのサイト・収集経路にあるURLを入力し、<strong>このURLで確認</strong>を押す。</li><li>別タブの実ページで、必要なら計測への同意を完了する。管理画面へページ名・説明・採用した候補・不採用理由が表示されます。保存前の設定案でも確認できます。</li><li>問題がなければ<strong>変更内容を確認 → 保存する</strong>を押す。</li></ol><p>確認は5分間有効です。最新版のSDKと、基本設定のメタデータ送信有効化が必要です。通常のJev判定・オファー表示・閲覧履歴保存は行いません。確認用の権限はこの管理者セッション・サイト・URLに限定し、接続開始に使えるのは1回です。</p><p>メタ情報がページ内で変わると結果も更新します。<strong>同じページから再取得</strong>でも再確認できます。設定案を変えると古い結果を消し、確認用の接続を終了します。変更後の内容で確認するには、もう一度<strong>このURLで確認</strong>を押してください。</p><p>接続できない場合は、タグの設置・更新、同意の完了、CSP、ポップアップの許可、Cross-Origin-Opener-Policyを確認します。COOPで別タブとの接続が切れるサイトは、この方式での確認を利用できません。SDK導入前や接続できない場合は、折り畳んだ人工データ入力でルールだけを試せます。実ページの測定とは区別して表示します。</p><p>既存サイトに取得設定がない場合は、切り替えて保存するまで従来のJSON-LD優先を維持します。保存後は次回SDKが設定を取得したときに適用します。変更前の閲覧履歴は破棄し、表示済み状態は保持します。取得キーと優先順位は<a href="./../integration/data">取得・送信されるデータ</a>を参照してください。</p><h2 id="urlの取得から除外するキー" tabindex="-1">URLの取得から除外するキー <a class="header-anchor" href="#urlの取得から除外するキー" aria-label="Permalink to “URLの取得から除外するキー”">​</a></h2><p>「ページ情報の取得」の先頭で、<strong>取得しないGETパラメータのキー</strong>を1行ずつ入力します。例えば<code>email</code>・<code>token</code>を指定すると、それらのキーと値を現在・流入ページと有効閲覧履歴のURLから除きます。未指定のGETパラメータは保持します。</p><p>右側に確認したいURLを入力すると、保存・送信するURLをその場で確認できます。この表示だけでは外部へ通信しません。除外設定はメタデータの標準・カスタム・従来モードのいずれでも保存できます。「変更内容を確認」から保存すると、次の設定読み込み時に適用します。開いたままの別タブへ即時反映はしません。</p><p>キーは大文字小文字を区別し、URLデコード後の完全一致で照合します。同じキーが複数あればすべて除きます。最大50件・各100文字です。詳細は<a href="./../integration/data#ページurlと除外キー">取得・送信されるデータ</a>を参照してください。</p>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};